package cn.zhuatech.expenseai.controller; import cn.zhuatech.expenseai.common.ApiResponse; import cn.zhuatech.expenseai.dto.ExpenseAiDto.*; import cn.zhuatech.expenseai.service.ExpenseAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final ExpenseAiService service;public OperationsAdminController(ExpenseAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
